// from src/locales/ja/blog.ts. Body + FAQs for article 'hex-vs-rgb-vs-hsl' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>画面の色には、いくつもの名前があります。同じ青でも#2563EB、rgb(37, 99, 235)、hsl(221, 83%, 53%)と表せて、どれもまったく同じピクセルを指します。</p>\n<p>この重なりが初心者を混乱させます。コードが互換なら、なぜ4つの形式があるのか。実際にはどれを使えばいいのか。</p>\n<p>この記事では、HEX、RGB、HSL、CMYKを並べて解説します。それぞれの意味、使われる場所、作業に合った形式の選び方まで分かります。</p>\n<h2 id=\"why-multiple-formats-exist\">なぜ複数の形式があるのか</h2>\n<p>仕事によって、色の説明に求められるものが違います。Web開発者はCSSに貼れる短いコードが欲しく、デザイナーは色相と明るさで色を説明したいからです。</p>\n<p>HEXは、コンピューターが色を保存する方法から生まれました。赤・緑・青の3バイトを16進数6桁で書いたもので、コンパクトでコピーしやすい形式です。</p>\n<p>RGBは、画面が色を作る方法から生まれました。赤・緑・青の光をそれぞれ0から255の強さで表す、直接的で読みやすい形式です。</p>\n<p>HSLは、人間が色を考える方法から生まれました。まず色相、次に鮮やかさ、最後に明るさ。多くのデザインツールのスライダーと同じ考え方です。</p>\n<h2 id=\"hex-explained\">HEXとは</h2>\n<p>HEXコードは#の後に16進数6桁が続きます。たとえば#2563EBです。最初の2桁が赤、次の2桁が緑、最後の2桁が青を表します。</p>\n<p>各ペアは16進数で00からFF、10進数では0から255の範囲です。つまり#FF0000は純粋な赤、#00FF00は純粋な緑、#000000は黒です。</p>\n<p>HEXはCSSと多くのデザインツールの標準形式です。短く、スタイルシートにきれいに貼れて、カラーピッカーからそのままコピーできます。</p>\n<p>短縮できるコードもあります。#336699は#369と書けます。各ペアの数字が2つとも同じ場合に限ります。意味は同じですが、ツールでは6桁の完全な形で表示されることが多いです。</p>\n<h2 id=\"rgb-explained\">RGBとは</h2>\n<p>RGBは同じ3つの値を10進数で書いたもので、たとえばrgb(37, 99, 235)です。各数値は0（その光なし）から255（最大）までの範囲です。</p>\n<p>RGBは、画面が実際に何をするかを最も素直に表しています。赤・緑・青の光をどれだけ混ぜるかをそのまま示すため、画像編集ソフトやカメラの内部でも使われています。</p>\n<p>RGBはRGBAで透明度にも対応します。4つ目の数値が不透明度で、rgba(37, 99, 235, 0.5)は同じ青を50%の不透明度で表します。</p>\n<p>多くのOffice系ソフトや文書ツールはRGB値を求めます。ブランドガイドに3つの数値で色が書かれている場合、たいていRGB形式です。</p>\n<h2 id=\"hsl-explained\">HSLとは</h2>\n<p>HSLは、色相・彩度・明度の3つの考え方で色を表します。典型的な値はhsl(221, 83%, 53%)です。</p>\n<p>色相は色相環上の角度で、0から360度です。赤が0度付近、緑が120度付近、青が240度付近で、360度で赤に戻ります。</p>\n<p>彩度は割合で、0%がグレー、100%が最も鮮やかな色相です。明度も割合で、0%が黒、50%が純粋な色相、100%が白です。</p>\n<p>HSLが力を発揮するのは、1色のバリエーションを作るときです。ボタンのホバー状態を明るくするには、色相と彩度をそのままに、明度を上げるだけ。新しい色を考える必要がありません。</p>\n<h2 id=\"cmyk-explained\">CMYKとは</h2>\n<p>CMYKは紙の上のインクで色を表します。シアン、マゼンタ、イエロー、ブラックをそれぞれ割合で示し、たとえばcmyk(84%, 58%, 0%, 8%)のようになります。</p>\n<p>プリンターはインクを減法混色で混ぜます。画面が光を足して白に近づくのとは逆で、白い紙から始めてインクを足して暗くしていく仕組みです。</p>\n<p>そのため、画面の色の中には正確に印刷できないものがあります。特に明るい青や緑はインクの再現範囲を超えやすく、印刷するとくすんで見えます。</p>\n<p><a href=\"/ja/gazou-iro-picker/\">画像カラーピッカー</a>が表示するCMYK値は、画面の色から計算した近似値です。印刷の打ち合わせの出発点として使い、正確な一致として扱わないようにしましょう。</p>\n<h2 id=\"hex-vs-rgb\">HEXとRGB、どちらを使うべきか</h2>\n<p>HEXとRGBは、同じ色を同じ3つの数値で、書き方だけを変えたものです。#2563EBとrgb(37, 99, 235)は、2つの表記の同じ青です。</p>\n<p>CSSや共有にはHEXを選びましょう。短く、スタイルシートの慣例であり、デザインツールやチャットにもきれいにコピーできます。</p>\n<p>ツールが3つの数値を求めるときや、透明度が必要なときはRGBを選びます。RGBAは、CSSで半透明の色を書く標準的な方法です。</p>\n<p>両者の変換は単純な計算です。HEXの各ペアを10進数に直すだけで、#25は37に、#63は99に、#EBは235になります。</p>\n<h2 id=\"hsl-vs-hex-rgb\">HSLが勝つ場面</h2>\n<p>HSLが勝つのは、1色の名前ではなく色のシステムを設計するときです。HSLで作ったパレットは、明度を変えても色相が固定されるため、一貫性が保たれます。</p>\n<p>ボタンの3つの状態を考えてみましょう。通常、ホバー、無効化です。HSLなら色相221、彩度83%を固定し、明度だけを53%、45%、70%と変えます。</p>\n<p>同じことをHEXでやると、関係の見えない3つのコードを考えることになります。見た目は問題なくても、コードからはそれらが仲間だと分かりません。</p>\n<p>多くのデザインツールはHSL入力に対応し、CSSも標準で使えます。色合いや明暗のバリエーションを作る作業では、HSLが整理しやすい形式です。</p>\n<h2 id=\"converting-between-formats\">形式どうしの変換</h2>\n<p>手作業での変換はほとんど必要ありません。カラーピッカーがすべての形式を一度に表示してくれるからです。それでも変換の仕組みを知れば、数値を信頼できるようになります。</p>\n<p>HEXからRGBへの変換は進数の変換です。16進数の各ペアが0から255の10進数になります。FFは255、80は128、00は0です。</p>\n<p>RGBからHSLへの変換は計算式です。3つの値の最大と最小から明度を求め、最も大きいチャンネルから色相を計算します。</p>\n<p>RGBからCMYKへの変換も計算式です。RGB値を反転させ、最小値をブラックとして、残りを調整します。だからこそCMYKの結果は測定値ではなく近似値なのです。</p>\n<h2 id=\"which-format-for-web\">Webではどの形式を使うべきか</h2>\n<p>ほとんどのWebサイトでは、HEXが安全な標準です。短く、あらゆる場所で使え、開発者なら誰でも一目で分かります。</p>\n<p>透明度が必要なときはRGBAを使います。半透明のオーバーレイや柔らかい影は、不透明度を1未満にしたrgbaで書くのが最も簡単です。</p>\n<p>体系的な色合いを持つテーマを作るときはHSLを使います。1つの色相から明暗のバリエーションを生み出すデザインシステムは、HSLだと管理がはるかに楽です。</p>\n<p>最近のCSSはOKLCHのような新しい形式にも対応しています。将来性はありますが、HEX、RGB、HSLは今もすべてのツールとブラウザが対応する形式です。</p>\n<h2 id=\"which-format-for-print\">印刷ではどの形式を使うべきか</h2>\n<p>印刷ではCMYKが作業言語です。印刷機はインクの割合で考えます。CMYKで用意したファイルなら、印刷所での予期せぬ変換を避けられます。</p>\n<p>まず画面の色からピッカーのCMYK近似値を控え、印刷の試し刷りで確認します。試し刷りこそが、唯一の真のテストです。</p>\n<p>HEXコードだけを渡して印刷を頼んではいけません。印刷所が変換しますが、その変換が自分なら選ばなかったインク値を選ぶかもしれません。</p>\n<p>ブランドの仕事では、印刷所のカラープロファイルをもらいましょう。プロファイルは、特定の印刷機と用紙に合わせて画面の色をインクに変換するもので、一般的な計算式より正確です。</p>\n<h2 id=\"which-format-for-design-tools\">デザインツールではどの形式を使うべきか</h2>\n<p>Figma、Photoshop、Canvaは、色の入力欄に貼ったHEXを受け付けます。抽出した色をデザインに移す最速の方法はHEXです。</p>\n<p>ツール内で色を調整するときは、色相・彩度・明度のスライダー、つまりHSL的な操作になります。表示はHEXでも、編集はHSLの考え方で行われます。</p>\n<p>ブランドガイドでは3つすべてを載せるのが一般的です。開発者向けにHEX、文書向けにRGB、印刷向けにCMYKです。それぞれの読み手が違う形式を使うからです。</p>\n<p><a href=\"/ja/iro-paretto-chushutsu/\">画像カラーパレット抽出ツール</a>でパレットを書き出すと、すべてのスウォッチにHEX、RGB、HSLが含まれます。自分で変換する必要はまったくありません。</p>\n<h2 id=\"common-mistakes\">カラーコードのよくある間違い</h2>\n<p>最も多い間違いは、HEXとRGBが違う色だと思い込むことです。2つの書き方の同じ値なので、#2563EBとrgb(37, 99, 235)は常に一致します。</p>\n<p>次に多いのは、CMYKの近似値を正確な値として扱うことです。画面から印刷への変換は計算式であり、実際の印刷色は印刷機やインク、紙によって変わります。</p>\n<p>明度と明るさを混同する人もいます。HSLで明度を100%に近づけると色は白に近づき、0%に近づけると黒に近づきます。</p>\n<p>最後に、違う画面で色を目だけで比べないこと。2台のモニターでは同じHEXコードでも違って見えるので、正確さが大切な場面では数値を信じましょう。</p>\n<h2 id=\"reading-a-color-picker-output\">カラーピッカーの表示の読み方</h2>\n<p>ピクセルを抽出すると、すべての形式が一度に表示されます。HEXコードはWeb用に、RGBの数値は文書用にコピーするのが基本です。</p>\n<p>HSL値は、色が色相環のどこにあり、どれだけ鮮やかかを教えてくれます。色相が0や360に近ければ赤、120に近ければ緑、240に近ければ青です。</p>\n<p>CMYKの割合は、その色に必要なインクの量を示します。シアンとマゼンタが高くイエローがなければ青、イエローが高くマゼンタが少しあればオレンジです。</p>\n<p>4つの形式を一目で読めるようになるには練習が必要ですが、身につければ大きな力になります。コードを見るだけで、貼る前に色を思い浮かべられるようになります。</p>\n<h2 id=\"building-a-palette-with-formats\">形式をまたいでパレットを作る</h2>\n<p>良いパレットは、1つの形式を正として、他をそこから作ります。多くのチームはHEXを正にします。開発者がコードに貼る形式だからです。</p>\n<p>HEXを基準に、明るい色と暗い色のバリエーションはHSLで作ります。明度だけを変えれば、色相の系統が保たれてパレットの一貫性が維持されます。</p>\n<p>RGB値は文書用に、CMYKの近似値は印刷用に記録します。4つの形式を載せたブランドガイドがあれば、誰もその場で変換する必要がありません。</p>\n<p>ピッカーから抽出した色をCSS変数として書き出し、その横にバリエーションを書き添えましょう。スタイルシートが、みんなが信頼する唯一の参照先になります。</p>\n<h2 id=\"hsl-and-accessibility\">HSLとアクセシビリティ：明度で考えるコントラスト</h2>\n<p>アクセシビリティのルールはコントラストを重視し、HSLはコントラストを考えやすくします。明度の値が大きく離れた2色はたいていコントラスト検査に通り、明度が近い2色は落ちます。</p>\n<p>明るい背景に濃い文字を考えてみましょう。文字の明度が15%付近、背景が95%付近なら、その差は大きく、ほぼすべての人にとって読みやすいテキストになります。</p>\n<p>ダークモードでも同じ理屈です。明度90%の明るい文字を、明度10%の暗い背景に置けば、同じ大きな差が生まれ、同じ読みやすさが得られます。</p>\n<p>HSLは、検査に落ちた組み合わせを性格を変えずに修正するのにも役立ちます。ボタンの色がコントラスト検査に落ちたら、色相と彩度はそのままに、明度を10ポイント下げるだけです。</p>\n<p>これはHEXで新しいコードを推測するよりはるかに簡単です。HEXでは、暗くした色は元の色と関係が見えない新しい数字の羅列になり、試すたびに新しい推測になります。</p>\n<p>デザインを監査するときは、主要な色をHSLに変換して明度順に並べてみましょう。文字色、背景色、アクセント色の間に十分な差があるかどうかが一目で分かります。</p>\n<p>色相と彩度は、それだけではコントラストにほとんど影響しないことも覚えておきましょう。鮮やかな赤と鮮やかな緑は明度がほぼ同じになることがあり、色覚に特性のある人には赤と緑の組み合わせが見分けにくくなります。</p>\n<h2 id=\"quick-reference\">早見表：形式チートシート</h2>\n<p>HEXは#の後の6桁、たとえば#2563EBです。CSSやデザインツール、文章で色を共有するときに使います。</p>\n<p>RGBは0から255の3つの数値、たとえばrgb(37, 99, 235)です。文書やOffice系ソフト、RGBAで透明度が必要なときに使います。</p>\n<p>HSLは色相の角度と彩度・明度の割合、たとえばhsl(221, 83%, 53%)です。色合いや明暗のバリエーション、テーマの作成に使います。</p>\n<p>CMYKは印刷用の4つのインク割合です。印刷物の出発点となる近似値として使い、必ず試し刷りで確認します。実際の操作は<a href=\"/ja/blog/gazou-iro-picker-kanzen-gaido/\">画像カラーピッカー完全ガイド</a>、手順は<a href=\"/ja/blog/gazou-kara-iro-o-toru-houhou/\">画像から色を抽出する方法</a>をご覧ください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Webサイトの色にはHEXとRGBのどちらが良いですか？","answer":"色そのものとしてはどちらも同じ値を表すので優劣はありません。HEXは短く、スタイルシートの慣例なので、多くの開発者が好みます。RGBは透明度が必要なときに優れています。RGBAは、HEXでは簡単に表せない不透明度の値を追加できます。"},{"question":"ブランドカラーが印刷では画面と違って見えるのはなぜですか？","answer":"画面は光で、印刷はインクで色を作るため、再現できる範囲が違います。画面の明るい青や緑は、インクでは再現できない範囲に入ることが多いです。ピッカーのCMYK値は近似値なので、大量に印刷する前に必ず試し刷りで確認してください。"},{"question":"ツールを使わずにHEXコードをHSLに変換できますか？","answer":"できますが、2段階の手順が必要です。まずHEXをRGBに変換し、次にRGBからHSLへの計算式を適用します。ピッカーなら両方の手順を瞬時に行い、すべての形式を一度に表示します。1回だけの変換なら、オンラインの変換ツールやピッカーを使う方が手計算より速いです。"},{"question":"HSLの色相の数字は実際に何を意味しますか？","answer":"色相は色相環上の0から360度の角度です。赤は0度付近、黄色は60度付近、緑は120度付近、シアンは180度付近、青は240度付近、マゼンタは300度付近です。色相が30度離れた色は似た印象になり、180度離れた色は補色として映えます。"},{"question":"WebサイトやSNS画像にCMYK値は必要ですか？","answer":"いいえ。Webサイトやアプリ、SNS画像はすべて画面のメディアなので、HEX、RGB、HSLのいずれかで十分です。CMYKが必要になるのはインクが紙に触れる印刷のときだけです。同じブランドカラーがいつか印刷される場合に備えて、CMYKの近似値は控えておくとよいでしょう。"},{"question":"HEXコードが3桁だけのものがあるのはなぜですか？","answer":"3桁のHEXコードは、各ペアの数字が2つとも同じ6桁コードの省略形です。#369は#336699を意味します。3が33に、6が66に、9が99になるからです。ペアがそろっていない6桁コードは短縮できません。"}];
